LRESULT CALLBACK WindowProc(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp) {
    switch (msg) {
        case WM_KEYDOWN:
            if (wp == VK_LEFT)  g_rect_x -= 5;
            if (wp == VK_RIGHT) g_rect_x += 5;
            InvalidateRect(hwnd, NULL, TRUE);
            break;
        case WM_PAINT: {
            PAINTSTRUCT ps;
            HDC hdc = BeginPaint(hwnd, &ps);
            RECT rc;
            GetClientRect(hwnd, &rc);
            int w = rc.right, h = rc.bottom;
            HDC back = CreateCompatibleDC(hdc);
            HBITMAP bmp = CreateCompatibleBitmap(hdc, w, h);
            HGDIOBJ old = SelectObject(back, bmp);

            FillRect(back, &rc, (HBRUSH)(COLOR_WINDOW + 1));
            RECT r;
            SetRect(&r, g_rect_x, g_rect_y, g_rect_x + 50, g_rect_y + 50);
            HBRUSH brush = CreateSolidBrush(RGB(0, 200, 100));
            FillRect(back, &r, brush);
            DeleteObject(brush);

            BitBlt(hdc, 0, 0, w, h, back, 0, 0, SRCCOPY);
            SelectObject(back, old);
            DeleteObject(bmp);
            DeleteDC(back);
            EndPaint(hwnd, &ps);
        } break;
        case WM_DESTROY:
            PostQuitMessage(0);
            break;
        default:
            return DefWindowProc(hwnd, msg, wp, lp);
